def raw_exercise():
    L = ['مشق', '']
    L += [f'{n}۔ {q}' for n, (q, _) in zip(['۱', '۲', '۳', '۴'], QS[:4])]
    L += ['۵۔ ذیل کے الفاظ اپنے جملوں میں استعمال کریں۔', '، '.join(w for w, _, _ in VOCAB) + '۔']
    L += ['۶۔ "وہم پرستی" پر ایک مضمون لکھیں۔']
    L += ['۷۔ مرکب ناقص: ' + GRAMMAR[0]['explanation'] + ' مثلاً: میرا قلم، اچھا گھوڑا، ٹھنڈا شربت۔',
          'مرکب تام: ' + GRAMMAR[1]['explanation'] + ' مثلاً: میرا قلم اچھا ہے، یہ شربت ٹھنڈا ہے، وہ اچھا کھلاڑی ہے۔ پانچ جملے لکھ کر ان میں مرکب ناقص اور مرکب تام کی نشاندہی کریں۔']
    L += ['۸۔ سیاق و سباق کا حوالہ دے کر مندرجہ ذیل اقتباس کی وضاحت کریں۔', PASSAGE]
    L += ['۹۔ درست جواب کا انتخاب کریں۔',
          '(i) سبق "انسان کسی حال میں خوش نہیں رہتا" کے مصنف کا نام ہے؟ (ا) سرسید (ب) اقبال (ج) محمد حسین آزاد (د) حالی',
          '(ii) غرض وہ سارا انبار عورتوں اور ______ میں تقسیم ہو گیا۔ (ا) بوڑھوں (ب) مردوں (ج) بیماروں (د) غلاموں',
          '(iii) چنانچہ بڈھے نے کہا کہ برائے خدا میرا ______ درد مجھے پھیر دیجیے۔ (ا) قولنج (ب) دل (ج) سر (د) کمر']
    L += ['', ACTIVITY, '', TEACHER]
    return '\n'.join(L)


def fix_exercise(ex):
    ex['rawExercise'] = raw_exercise()
    ex['blanks'] = []
    ex['shortQuestions'] = [dict(question=q, answer=a) for q, a in QS]
    ex['vocabulary'] = [dict(word=w, meaning=m, sentence=s) for w, m, s in VOCAB]
    ex['grammar'] = GRAMMAR
    ex['textbookMcqs'] = [
        dict(question='سبق "انسان کسی حال میں خوش نہیں رہتا" کے مصنف کا نام ہے؟', options=['سرسید', 'اقبال', 'محمد حسین آزاد', 'حالی'], correct=2),
        dict(question='غرض وہ سارا انبار عورتوں اور ______ میں تقسیم ہو گیا۔', options=['بوڑھوں', 'مردوں', 'بیماروں', 'غلاموں'], correct=1),
        dict(question='چنانچہ بڈھے نے کہا کہ برائے خدا میرا ______ درد مجھے پھیر دیجیے۔', options=['قولنج', 'دل', 'سر', 'کمر'], correct=0),
    ]
    ex['activity'] = ACTIVITY.split(': ', 1)[1]
